def transform(grid):
    """Stamp the rare-color marker shape at positions where its cells are 0."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    color = min((c for c in counts if c != 0), key=lambda c: counts[c])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    min_r = min(r for r, c in points)
    min_c = min(c for r, c in points)
    shape = {(r - min_r, c - min_c) for r, c in points}
    shape_h = max(r for r, c in shape) + 1
    shape_w = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for top in range(h - shape_h + 1):
        for left in range(w - shape_w + 1):
            if all(grid[top + dr][left + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[top + dr][left + dc] = color
    return out

